def calc_bmi(weight, height):
    bmi = weight / (height ** 2)
    return round(bmi, 1)

def judge_bmi(bmi):
    if bmi < 18.5:
        return "低体重"
    elif bmi < 25:
        return "標準"
    else:
        return "肥満"

weight = 60
height = 1.7

bmi = calc_bmi(weight, height)
result = judge_bmi(bmi)

print("BMI: " + str(bmi))
print("判定: " + result)

questions = {
    "Pythonの作者は?": "グイド",
    "1 + 1 = ?": "2",
    "日本の首都は?": "東京"
}

score = 0
for question, answer in questions.items():
    print(question)
    user_answer = answer  # テスト用に正解を入れる
    if user_answer == answer:
        score += 1
        print("正解!")
    else:
        print("不正解...")

print("\n結果: " + str(score) + " / " + str(len(questions)) + " 点")

