# タスク管理アプリ
class Task:
    def __init__(self, title):
        self.title = title
        self.done = False

    def complete(self):
        self.done = True

class TaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, title):
        task = Task(title)
        self.tasks.append(task)

    def show_tasks(self):
        print("=== タスク一覧 ===")
        for i, task in enumerate(self.tasks, 1):
            status = "✓" if task.done else " "
            print(f"{i}. [{status}] {task.title}")

manager = TaskManager()
manager.add_task("Pythonの勉強")
manager.add_task("買い物に行く")
manager.tasks[0].complete()
manager.show_tasks()
